import React from 'react';
import '../styles/Servicios.css';

const AuditoriaFinanciera = () => (
  <div className="servicios-container">
    <h2 className="servicios-title">Auditoría Financiera</h2>
    <p>Revisión y análisis detallado de los procesos financieros y contables, garantizando transparencia, confiabilidad y cumplimiento normativo.</p>
  </div>
);

export default AuditoriaFinanciera;
